/* A single decorative sampling layer; content never enters its filter chain. */
.material-surface{background:rgba(24,25,29,.36)}
:root[data-material-theme='light'] .material-surface{background:rgba(255,255,255,.46)}
.material-surface>.material-transmission{position:absolute;inset:0;z-index:-1;pointer-events:none;border-radius:inherit;overflow:hidden;background-image:linear-gradient(rgba(12,13,17,.60),rgba(12,13,17,.60)),url('./cozy-beige-room-photo-1920.webp');background-repeat:no-repeat;filter:blur(7px);transform:none}
:root[data-material-theme='light'] .material-transmission{background-image:linear-gradient(rgba(255,255,255,.50),rgba(255,255,255,.50)),url('./cozy-beige-room-photo-1920.webp')}
:root[data-material-optics='svg'] .material-transmission{filter:url('#material-refraction')}
:root[data-material-background='solid'] .material-transmission{display:none}
:root[data-material-background='solid'] .material-surface{background:linear-gradient(180deg,var(--surface-top),var(--surface-mid) 25%,var(--surface-low) 64%)}
